def act(step, task):
    if step.tool not in ALLOWLIST[task.kind]:      # least privilege
        return Refused("tool not permitted for this task")
    if detector.flags(step.args):                 # a classifier, so it has an ROC
        return Refused("input flagged")
    if RISK[step.tool] >= 2:                       # confirm by RISK, not uniformly
        return NeedsConfirmation(step)
    return execute(step)
